def subtract(a, b):
    # Filter out empty intervals and normalize
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    # If a is empty, return empty list
    if not a_intervals:
        return []

    # If b is empty, just merge a and return
    if not b_intervals:
        return merge_intervals(a_intervals)

    # Sort both lists
    a_intervals.sort()
    b_intervals.sort()

    # Merge b to get non-overlapping intervals
    b_merged = merge_intervals(b_intervals)

    # Subtract b_merged from a
    result = []
    for a_start, a_end in a_intervals:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    next_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts outside b
                    if curr_start < b_start:
                        next_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
                        next_intervals.append([b_end, curr_end])
            current_intervals = next_intervals

        result.extend(current_intervals)

    # Merge touching intervals
    return merge_intervals(result)


def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start point
    intervals.sort()

    merged = [intervals[0]]

    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]

        # If current interval overlaps or touches the last merged interval
        if start <= last_end:
            # Merge them
            merged[-1] = [last_start, max(last_end, end)]
        else:
            # No overlap, add as new interval
            merged.append([start, end])

    return merged

